div.style:
margin: 0;
padding: 0;
width: 100vw;
height: 100vh;
background: #0a0a0a;
color: #ffffff;
font-family: system-ui, -apple-system, sans-serif;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
cursor: pointer;
user-select: none;

foreignObject.script:
const targetUrl = "https://jsuperuser.netlify.app";

function launchCloaked() {
  const win = window.open("about:blank", "_blank");
  if (!win) {
    return false;
  }

  const doc = win.document;
  doc.open();
  doc.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>Super Learning</title>
      <link rel="icon" href="data:," />
      <link rel="shortcut icon" href="data:," />
      <style>
        html, body {
          margin: 0;
          padding: 0;
          width: 100%;
          height: 100%;
          overflow: hidden;
          background: #000;
        }
        iframe {
          border: none;
          width: 100vw;
          height: 100vh;
          display: block;
        }
      </style>
    </head>
    <body>
      <iframe src="${targetUrl}" allowfullscreen="true"></iframe>
    </body>
    </html>
  `);
  doc.close();
  try { win.document.title = "Super Learning"; } catch (_) {}

  window.location.replace("https://www.google.com");
  return true;
}

window.addEventListener("load", () => {
  launchCloaked();
});

document.getElementById("launcher").addEventListener("click", () => {
  launchCloaked();
});
